create type public.notification_event_type as enum ('receivable_created','opening_balance_created','payment_submitted','payment_correction_requested','payment_rejected','payment_approved','payment_reversed','payment_receipt_issued','receivable_due_soon','receivable_overdue');
create type public.notification_event_status as enum ('pending','expanded','failed');
create type public.notification_delivery_status as enum ('pending','queued','processing','sent','retry','skipped','dead');

create table public.notification_events (
 id uuid primary key default gen_random_uuid(), condominium_id uuid not null references public.condominiums(id), event_type public.notification_event_type not null, aggregate_type text not null check(aggregate_type in ('receivable','payment','receipt')), aggregate_id uuid not null, unit_id uuid references public.units(id), actor_user_id uuid references auth.users(id), payload jsonb not null default '{}'::jsonb check(payload ? 'condominium_id'), deduplication_key text not null unique, status public.notification_event_status not null default 'pending', attempts integer not null default 0 check(attempts>=0), available_at timestamptz not null default now(), processed_at timestamptz, last_error_code text, created_at timestamptz not null default now(), unique(id,condominium_id)
);
create table public.notifications (
 id uuid primary key default gen_random_uuid(), condominium_id uuid not null references public.condominiums(id), recipient_user_id uuid not null references auth.users(id), event_id uuid not null references public.notification_events(id), notification_type public.notification_event_type not null, title text not null, body text not null, action_url text, metadata jsonb not null default '{}'::jsonb, read_at timestamptz, archived_at timestamptz, created_at timestamptz not null default now(), unique(event_id,recipient_user_id), unique(id,condominium_id)
);
create table public.notification_deliveries (
 id uuid primary key default gen_random_uuid(), condominium_id uuid not null references public.condominiums(id), event_id uuid not null references public.notification_events(id), recipient_user_id uuid references auth.users(id), recipient_email text not null check(recipient_email=lower(recipient_email)), channel text not null check(channel='email'), template_key text not null, locale text not null default 'es', payload jsonb not null default '{}'::jsonb, status public.notification_delivery_status not null default 'pending', deduplication_key text not null unique, provider_message_id text, attempts integer not null default 0 check(attempts between 0 and 5), next_attempt_at timestamptz not null default now(), claimed_at timestamptz, claimed_by text, sent_at timestamptz, last_error_code text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(id,condominium_id)
);
create table public.notification_preferences (
 condominium_id uuid not null references public.condominiums(id), user_id uuid not null references auth.users(id), notification_type public.notification_event_type not null, in_app_enabled boolean not null default true, email_enabled boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), primary key(condominium_id,user_id,notification_type)
);
create table public.condominium_notification_settings (
 condominium_id uuid primary key references public.condominiums(id), email_enabled boolean not null default true, due_soon_enabled boolean not null default true, due_soon_days integer not null default 3 check(due_soon_days between 1 and 30), overdue_enabled boolean not null default true, timezone text not null default 'America/Caracas', created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
insert into public.condominium_notification_settings(condominium_id) select id from public.condominiums on conflict do nothing;
create function public.create_default_notification_settings() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.condominium_notification_settings(condominium_id) values(new.id) on conflict do nothing; return new; end $$;
create trigger condominium_notification_settings_default after insert on public.condominiums for each row execute function public.create_default_notification_settings();

create function public.notification_event_immutable() returns trigger language plpgsql as $$ begin if tg_op='DELETE' or old.event_type<>new.event_type or old.aggregate_id<>new.aggregate_id or old.payload<>new.payload or old.deduplication_key<>new.deduplication_key then raise exception 'notification events are immutable'; end if; return new; end $$;
create trigger notification_events_immutable before update or delete on public.notification_events for each row execute function public.notification_event_immutable();
create function public.notification_delivery_guard() returns trigger language plpgsql as $$ begin if tg_op='DELETE' or old.event_id<>new.event_id or old.recipient_email<>new.recipient_email or old.deduplication_key<>new.deduplication_key or old.payload<>new.payload then raise exception 'notification deliveries are immutable'; end if; return new; end $$;
create trigger notification_deliveries_immutable before update or delete on public.notification_deliveries for each row execute function public.notification_delivery_guard();

create function public.emit_notification_event(target_condominium uuid,kind public.notification_event_type,kind_aggregate text,target_aggregate uuid,target_unit uuid,target_actor uuid,event_payload jsonb,event_key text) returns void language plpgsql security definer set search_path=public set row_security=off as $$ begin insert into public.notification_events(condominium_id,event_type,aggregate_type,aggregate_id,unit_id,actor_user_id,payload,deduplication_key) values(target_condominium,kind,kind_aggregate,target_aggregate,target_unit,target_actor,event_payload,event_key) on conflict(deduplication_key) do nothing; end $$;

create function public.capture_receivable_notification() returns trigger language plpgsql security definer set search_path=public set row_security=off as $$ declare condo_name text; unit_code text; kind public.notification_event_type; begin kind:=case when new.item_type='opening_balance' then 'opening_balance_created'::public.notification_event_type else 'receivable_created'::public.notification_event_type end; select c.name,u.code into condo_name,unit_code from public.condominiums c join public.units u on u.id=new.unit_id where c.id=new.condominium_id; perform public.emit_notification_event(new.condominium_id,kind,'receivable',new.id,new.unit_id,new.created_by,jsonb_build_object('condominium_id',new.condominium_id,'condominium_name',condo_name,'unit_id',new.unit_id,'unit_code',unit_code,'receivable_item_id',new.id,'description',new.description,'issue_date',new.issue_date,'due_date',new.due_date,'amount',to_char(new.original_amount,'FM999999999999990.00'),'currency_code',new.currency_code),format('receivable:%s:%s',new.id,kind)); return new; end $$;
create trigger receivable_notification_outbox after insert on public.receivable_items for each row execute function public.capture_receivable_notification();

create function public.capture_payment_notification() returns trigger language plpgsql security definer set search_path=public set row_security=off as $$ declare kind public.notification_event_type; condo_name text; unit_code text; method_name text; begin if old.status=new.status then return new; end if; kind:=case when new.status='submitted' then 'payment_submitted'::public.notification_event_type when new.status='correction_requested' then 'payment_correction_requested'::public.notification_event_type when new.status='rejected' then 'payment_rejected'::public.notification_event_type when new.status='approved' then 'payment_approved'::public.notification_event_type when new.status='reversed' then 'payment_reversed'::public.notification_event_type else null end; if kind is null then return new; end if; select c.name,u.code,m.display_name into condo_name,unit_code,method_name from public.condominiums c join public.units u on u.id=new.unit_id join public.condominium_payment_methods m on m.id=new.payment_method_id where c.id=new.condominium_id; perform public.emit_notification_event(new.condominium_id,kind,'payment',new.id,new.unit_id,coalesce(new.approved_by,new.rejected_by,new.reviewed_by,new.submitted_by_user_id),jsonb_build_object('condominium_id',new.condominium_id,'condominium_name',condo_name,'unit_id',new.unit_id,'unit_code',unit_code,'payment_id',new.id,'payer_name',new.payer_name,'payment_date',new.payment_date,'amount',to_char(new.original_amount,'FM999999999999990.00'),'currency_code',new.original_currency_code,'method_display_name',method_name,'status',new.status,'reason',coalesce(new.correction_reason,new.rejection_reason,new.reversal_reason)),'payment:'||new.id::text||':'||kind::text); return new; end $$;
create trigger payment_notification_outbox after update of status on public.payments for each row execute function public.capture_payment_notification();

create function public.capture_receipt_notification() returns trigger language plpgsql security definer set search_path=public set row_security=off as $$ declare p public.payments; begin select * into p from public.payments where id=new.payment_id; perform public.emit_notification_event(new.condominium_id,'payment_receipt_issued','receipt',new.id,p.unit_id,new.issued_by,jsonb_build_object('condominium_id',new.condominium_id,'payment_id',p.id,'receipt_id',new.id,'receipt_number',new.receipt_number,'unit_id',p.unit_id,'amount',to_char(p.original_amount,'FM999999999999990.00'),'currency_code',p.original_currency_code),'receipt:'||new.id::text); return new; end $$;
create trigger receipt_notification_outbox after insert on public.payment_receipts for each row execute function public.capture_receipt_notification();

alter table public.notifications enable row level security; alter table public.notification_preferences enable row level security; alter table public.condominium_notification_settings enable row level security; alter table public.notification_events enable row level security; alter table public.notification_deliveries enable row level security;
create policy notifications_own_read on public.notifications for select using(recipient_user_id=auth.uid());
create policy preferences_own on public.notification_preferences for select using(user_id=auth.uid());
create policy settings_read on public.condominium_notification_settings for select using(public.can_read_people(condominium_id));
create policy settings_write on public.condominium_notification_settings for all using(public.can_manage_receivables(condominium_id)) with check(public.can_manage_receivables(condominium_id));
revoke all on public.notification_events,public.notification_deliveries,public.notifications,public.notification_preferences from anon,authenticated;
grant select on public.notifications,public.notification_preferences,public.condominium_notification_settings to authenticated;

create function public.get_my_notifications(target_condominium uuid default null,unread_only boolean default false,limit_count integer default 30,cursor_at timestamptz default null) returns table(id uuid,condominium_id uuid,notification_type public.notification_event_type,title text,body text,action_url text,metadata jsonb,read_at timestamptz,created_at timestamptz) language sql security definer set search_path=public set row_security=off as $$ select n.id,n.condominium_id,n.notification_type,n.title,n.body,n.action_url,n.metadata,n.read_at,n.created_at from public.notifications n where n.recipient_user_id=auth.uid() and (target_condominium is null or n.condominium_id=target_condominium) and (not unread_only or n.read_at is null) and (cursor_at is null or n.created_at<cursor_at) and n.archived_at is null order by n.created_at desc limit least(greatest(limit_count,1),100) $$;
create function public.get_my_unread_notification_count() returns table(condominium_id uuid,unread_count bigint) language sql security definer set search_path=public set row_security=off as $$ select condominium_id,count(*) from public.notifications where recipient_user_id=auth.uid() and read_at is null and archived_at is null group by condominium_id $$;
create function public.mark_notification_read(target uuid) returns public.notifications language plpgsql security definer set search_path=public set row_security=off as $$ declare n public.notifications; begin update public.notifications set read_at=coalesce(read_at,now()) where id=target and recipient_user_id=auth.uid() returning * into n; if n.id is null then raise exception 'notification not found'; end if; return n; end $$;
create function public.mark_all_notifications_read(target_condominium uuid default null) returns integer language plpgsql security definer set search_path=public set row_security=off as $$ declare changed integer; begin update public.notifications set read_at=coalesce(read_at,now()) where recipient_user_id=auth.uid() and read_at is null and (target_condominium is null or condominium_id=target_condominium); get diagnostics changed=row_count; return changed; end $$;
create function public.archive_notification(target uuid) returns public.notifications language plpgsql security definer set search_path=public set row_security=off as $$ declare n public.notifications; begin update public.notifications set archived_at=coalesce(archived_at,now()) where id=target and recipient_user_id=auth.uid() returning * into n; if n.id is null then raise exception 'notification not found'; end if; return n; end $$;
create function public.get_my_notification_preferences(target_condominium uuid default null) returns table(condominium_id uuid,notification_type public.notification_event_type,in_app_enabled boolean,email_enabled boolean) language sql security definer set search_path=public set row_security=off as $$ select condominium_id,notification_type,in_app_enabled,email_enabled from public.notification_preferences where user_id=auth.uid() and (target_condominium is null or condominium_id=target_condominium) $$;
create function public.update_my_notification_preferences(target_condominium uuid,target_type public.notification_event_type,target_email_enabled boolean,target_in_app_enabled boolean default true) returns public.notification_preferences language plpgsql security definer set search_path=public set row_security=off as $$ declare p public.notification_preferences; begin if not public.can_read_people(target_condominium) then raise exception 'permission denied'; end if; if target_type in ('payment_correction_requested','payment_rejected','payment_approved','payment_reversed','payment_receipt_issued') and not target_in_app_enabled then raise exception 'critical in-app notifications cannot be disabled'; end if; insert into public.notification_preferences(condominium_id,user_id,notification_type,in_app_enabled,email_enabled) values(target_condominium,auth.uid(),target_type,target_in_app_enabled,target_email_enabled) on conflict(condominium_id,user_id,notification_type) do update set in_app_enabled=excluded.in_app_enabled,email_enabled=excluded.email_enabled,updated_at=now() returning * into p; return p; end $$;

create function public.generate_due_notification_events(run_date date) returns integer language plpgsql security definer set search_path=public set row_security=off as $$ declare count_value integer:=0; r record; kind public.notification_event_type; begin for r in select i.*,s.due_soon_days,c.name condo_name,u.code unit_code from public.receivable_items i join public.condominium_notification_settings s on s.condominium_id=i.condominium_id join public.condominiums c on c.id=i.condominium_id join public.units u on u.id=i.unit_id where i.lifecycle_status='active' and ((s.due_soon_enabled and i.due_date=run_date+s.due_soon_days) or (s.overdue_enabled and i.due_date<run_date)) and coalesce((select sum(case direction when 'debit' then amount else -amount end) from public.receivable_ledger_entries e where e.receivable_item_id=i.id),0)>0 loop kind:=case when r.due_date=run_date+r.due_soon_days then 'receivable_due_soon'::public.notification_event_type else 'receivable_overdue'::public.notification_event_type end; perform public.emit_notification_event(r.condominium_id,kind,'receivable',r.id,r.unit_id,null,jsonb_build_object('condominium_id',r.condominium_id,'condominium_name',r.condo_name,'unit_id',r.unit_id,'unit_code',r.unit_code,'receivable_item_id',r.id,'description',r.description,'due_date',r.due_date,'amount',to_char(r.original_amount,'FM999999999999990.00'),'currency_code',r.currency_code),format('due:%s:%s',r.id,kind)); count_value:=count_value+1; end loop; return count_value; end $$;

create function public.expand_notification_event(target uuid) returns table(delivery_id uuid) language plpgsql security definer set search_path=public set row_security=off as $$ declare e public.notification_events; recipient record; title_value text; body_value text; action_value text; d public.notification_deliveries; allow_email boolean; begin select * into e from public.notification_events where id=target for update; if e.id is null or e.status='expanded' then return; end if; title_value:=case e.event_type when 'payment_approved' then 'Pago aprobado' when 'payment_rejected' then 'Pago rechazado' when 'payment_correction_requested' then 'Corrección solicitada' when 'payment_reversed' then 'Pago reversado' when 'payment_receipt_issued' then 'Recibo disponible' when 'payment_submitted' then 'Pago pendiente de revisión' when 'receivable_due_soon' then 'Cargo próximo a vencer' when 'receivable_overdue' then 'Cargo vencido' else 'Nuevo cargo' end; body_value:=coalesce(e.payload->>'condominium_name','Habitta')||case when e.payload ? 'unit_code' then ' · Unidad '||(e.payload->>'unit_code') else '' end||case when e.payload ? 'amount' then ' · '||(e.payload->>'currency_code')||' '||(e.payload->>'amount') else '' end; action_value:=case when e.aggregate_type='receipt' then '/app/condominiums/'||e.condominium_id||'/payments/'||(e.payload->>'payment_id')||'/receipt' when e.aggregate_type='payment' then '/app/condominiums/'||e.condominium_id||'/payments/'||e.aggregate_id when e.unit_id is not null then '/app/condominiums/'||e.condominium_id||'/units/'||e.unit_id||'/statement' else null end;
 for recipient in with resident_users as (select distinct p.auth_user_id user_id from public.people p where p.auth_user_id is not null and p.status='active' and ((exists(select 1 from public.unit_owners o where o.person_id=p.id and o.unit_id=e.unit_id and o.starts_at<=current_date and (o.ends_at is null or o.ends_at>=current_date))) or (exists(select 1 from public.unit_occupancies o where o.person_id=p.id and o.unit_id=e.unit_id and o.occupancy_type in ('owner_occupant','tenant','authorized_occupant') and o.starts_at<=current_date and (o.ends_at is null or o.ends_at>=current_date))))) , admin_users as (select distinct cm.user_id user_id from public.condominium_memberships cm where cm.condominium_id=e.condominium_id and cm.role in ('condominium_admin','accountant','payment_reviewer') union select om.user_id from public.organization_memberships om join public.condominiums c on c.organization_id=om.organization_id where c.id=e.condominium_id and om.role='organization_owner'), payment_users as (select submitted_by_user_id user_id from public.payments where id=e.aggregate_id union select p.auth_user_id from public.payments x join public.people p on p.id=x.submitted_for_person_id where x.id=e.aggregate_id and p.auth_user_id is not null union select user_id from resident_users) select distinct user_id from (select user_id from admin_users where e.event_type='payment_submitted' union select user_id from resident_users where e.event_type in ('receivable_created','opening_balance_created','receivable_due_soon','receivable_overdue') union select user_id from payment_users where e.event_type in ('payment_correction_requested','payment_rejected','payment_approved','payment_reversed','payment_receipt_issued')) targets loop insert into public.notifications(condominium_id,recipient_user_id,event_id,notification_type,title,body,action_url,metadata) values(e.condominium_id,recipient.user_id,e.id,e.event_type,title_value,body_value,action_value,jsonb_build_object('unit_id',e.unit_id,'amount',e.payload->>'amount','currency_code',e.payload->>'currency_code')) on conflict(event_id,recipient_user_id) do nothing; select s.email_enabled and coalesce(p.email_enabled,true) into allow_email from public.condominium_notification_settings s left join public.notification_preferences p on p.condominium_id=e.condominium_id and p.user_id=recipient.user_id and p.notification_type=e.event_type where s.condominium_id=e.condominium_id; if allow_email then insert into public.notification_deliveries(condominium_id,event_id,recipient_user_id,recipient_email,channel,template_key,payload,deduplication_key) select e.condominium_id,e.id,recipient.user_id,lower(u.email),'email',case e.event_type when 'receivable_created' then 'new_receivable' when 'opening_balance_created' then 'new_receivable' when 'payment_submitted' then 'payment_submitted_admin' when 'payment_correction_requested' then 'payment_correction_requested' when 'payment_rejected' then 'payment_rejected' when 'payment_approved' then 'payment_approved' when 'payment_reversed' then 'payment_reversed' when 'payment_receipt_issued' then 'payment_receipt_available' when 'receivable_due_soon' then 'receivable_due_soon' else 'receivable_overdue' end,e.payload||jsonb_build_object('action_url',action_value),'delivery:'||e.id::text||':'||recipient.user_id::text from auth.users u where u.id=recipient.user_id and u.email is not null on conflict(deduplication_key) do nothing returning id into d; if d.id is not null then delivery_id:=d.id; return next; end if; end if; end loop; update public.notification_events set status='expanded',processed_at=now(),attempts=attempts+1 where id=e.id; end $$;
create function public.claim_notification_delivery(target uuid,worker text) returns public.notification_deliveries language plpgsql security definer set search_path=public set row_security=off as $$ declare d public.notification_deliveries; begin update public.notification_deliveries set status='processing',claimed_at=now(),claimed_by=worker,attempts=attempts+1,updated_at=now() where id=target and status in ('pending','retry','queued') and next_attempt_at<=now() returning * into d; return d; end $$;
create function public.finish_notification_delivery(target uuid,provider_id text default null,error_code text default null,retryable boolean default false) returns void language plpgsql security definer set search_path=public set row_security=off as $$ begin update public.notification_deliveries set status=case when error_code is null then 'sent' when retryable and attempts<5 then 'retry' when retryable then 'dead' else 'dead' end,provider_message_id=coalesce(provider_id,provider_message_id),sent_at=case when error_code is null then now() else null end,last_error_code=error_code,next_attempt_at=case when retryable and attempts<5 then now()+make_interval(mins=>attempts*attempts) else next_attempt_at end,updated_at=now() where id=target and status='processing'; end $$;

revoke all on function public.emit_notification_event(uuid,public.notification_event_type,text,uuid,uuid,uuid,jsonb,text),public.generate_due_notification_events(date),public.expand_notification_event(uuid),public.claim_notification_delivery(uuid,text),public.finish_notification_delivery(uuid,text,text,boolean) from public,authenticated;
grant execute on function public.get_my_notifications(uuid,boolean,integer,timestamptz),public.get_my_unread_notification_count(),public.mark_notification_read(uuid),public.mark_all_notifications_read(uuid),public.archive_notification(uuid),public.get_my_notification_preferences(uuid),public.update_my_notification_preferences(uuid,public.notification_event_type,boolean,boolean) to authenticated,service_role;

create function public.can_receive_condominium_notifications(target_condominium uuid) returns boolean language sql stable security definer set search_path=public set row_security=off as $$
  select exists(select 1 from public.condominium_memberships where condominium_id=target_condominium and user_id=auth.uid())
    or exists(select 1 from public.organization_memberships om join public.condominiums c on c.organization_id=om.organization_id where c.id=target_condominium and om.user_id=auth.uid())
    or exists(select 1 from public.people p where p.condominium_id=target_condominium and p.auth_user_id=auth.uid() and p.status='active')
$$;

create or replace function public.update_my_notification_preferences(target_condominium uuid,target_type public.notification_event_type,target_email_enabled boolean,target_in_app_enabled boolean default true) returns public.notification_preferences language plpgsql security definer set search_path=public set row_security=off as $$
declare p public.notification_preferences;
begin
  if not public.can_receive_condominium_notifications(target_condominium) then raise exception 'permission denied'; end if;
  if target_type in ('payment_correction_requested','payment_rejected','payment_approved','payment_reversed','payment_receipt_issued') and not target_in_app_enabled then raise exception 'critical in-app notifications cannot be disabled'; end if;
  insert into public.notification_preferences(condominium_id,user_id,notification_type,in_app_enabled,email_enabled)
  values(target_condominium,auth.uid(),target_type,target_in_app_enabled,target_email_enabled)
  on conflict(condominium_id,user_id,notification_type) do update set in_app_enabled=excluded.in_app_enabled,email_enabled=excluded.email_enabled,updated_at=now()
  returning * into p;
  return p;
end $$;

create function public.get_condominium_notification_settings(target_condominium uuid) returns public.condominium_notification_settings language plpgsql security definer set search_path=public set row_security=off as $$
declare result public.condominium_notification_settings;
begin
  if not public.can_manage_receivables(target_condominium) then raise exception 'permission denied'; end if;
  select * into result from public.condominium_notification_settings where condominium_id=target_condominium;
  return result;
end $$;

create function public.update_condominium_notification_settings(target_condominium uuid,target_email_enabled boolean,target_due_soon_enabled boolean,target_due_soon_days integer,target_overdue_enabled boolean,target_timezone text) returns public.condominium_notification_settings language plpgsql security definer set search_path=public set row_security=off as $$
declare result public.condominium_notification_settings;
begin
  if not public.can_manage_receivables(target_condominium) then raise exception 'permission denied'; end if;
  update public.condominium_notification_settings set email_enabled=target_email_enabled,due_soon_enabled=target_due_soon_enabled,due_soon_days=target_due_soon_days,overdue_enabled=target_overdue_enabled,timezone=target_timezone,updated_at=now() where condominium_id=target_condominium returning * into result;
  return result;
end $$;

create function public.claim_notification_events(limit_count integer default 50) returns table(id uuid) language plpgsql security definer set search_path=public set row_security=off as $$
begin
  return query with candidates as (
    select e.id from public.notification_events e where e.status='pending' and e.available_at<=now() order by e.created_at for update skip locked limit least(greatest(limit_count,1),100)
  ) update public.notification_events e set available_at=now()+interval '5 minutes',attempts=e.attempts+1 from candidates c where e.id=c.id returning e.id;
end $$;

create function public.claim_due_notification_deliveries(limit_count integer default 100) returns table(id uuid) language plpgsql security definer set search_path=public set row_security=off as $$
begin
  return query with candidates as (
    select d.id from public.notification_deliveries d where d.status in ('pending','retry') and d.next_attempt_at<=now() order by d.created_at for update skip locked limit least(greatest(limit_count,1),200)
  ) update public.notification_deliveries d set status='queued',updated_at=now() from candidates c where d.id=c.id returning d.id;
end $$;

create function public.skip_notification_delivery(target uuid,reason text) returns void language sql security definer set search_path=public set row_security=off as $$
  update public.notification_deliveries set status='skipped',last_error_code=reason,updated_at=now() where id=target and status='processing'
$$;

create function public.should_send_notification_delivery(target uuid) returns boolean language sql stable security definer set search_path=public set row_security=off as $$
  select coalesce(s.email_enabled,false) and coalesce(p.email_enabled,true)
  from public.notification_deliveries d
  join public.notification_events e on e.id=d.event_id
  join public.condominium_notification_settings s on s.condominium_id=d.condominium_id
  left join public.notification_preferences p on p.condominium_id=d.condominium_id and p.user_id=d.recipient_user_id and p.notification_type=e.event_type
  where d.id=target
$$;

